import{_ as t,I as r,g as s,j as a}from"./chunks/framework.Ha9mtr6N.js";const h=JSON.parse('{"title":"Производство (Верстак)","description":"Управление очередью заказов, динамическое резервирование материалов и выпуск готовой продукции.","frontmatter":{"title":"Производство (Верстак)","description":"Управление очередью заказов, динамическое резервирование материалов и выпуск готовой продукции.","order":7},"headers":[],"relativePath":"ru/docs/spaces/production/workbench.md","filePath":"ru/docs/spaces/production/workbench.md"}'),e={name:"ru/docs/spaces/production/workbench.md"};function n(i,o,l,c,p,d){return r(),s("div",null,[...o[0]||(o[0]=[a('<div class="warning custom-block"><p class="custom-block-title">📌 Документация находится в разработке</p><p><strong>Уважаемые пользователи!</strong></p><p>Поскольку ОмниКрафт ЕРП сейчас находится в стадии активной бета-версии, регулярно дорабатывается и расширяется, справочные материалы также обновляются постепенно.</p><p>На данный момент воспринимайте документацию как ориентировочную — она является неполной, может временно не содержать описание некоторых функций или содержать неточности.</p></div><h1 id="🔨-производство-верстак-и-очередь-пошива" tabindex="-1">🔨 Производство: Верстак и Очередь пошива <a class="header-anchor" href="#🔨-производство-верстак-и-очередь-пошива" aria-label="Permalink to &quot;🔨 Производство: Верстак и Очередь пошива&quot;">​</a></h1><p>Вкладка <strong>«Производство»</strong> (Верстак) — это ваш диспетчерский пульт. Сюда попадают все партии изделий, которые вы запланировали во вкладке «Калькулятор».</p><p>Главная особенность Верстака в ОмниКрафт ЕРП — <strong>динамическое планирование без жестких блокировок</strong>. Добавление заказа на верстак <em>не списывает</em> материалы со склада мгновенно. Вместо этого программа создает «мягкий резерв».</p><hr><h2 id="🚦-динамическая-очередь-и-приоритеты" tabindex="-1">🚦 Динамическая очередь и Приоритеты <a class="header-anchor" href="#🚦-динамическая-очередь-и-приоритеты" aria-label="Permalink to &quot;🚦 Динамическая очередь и Приоритеты&quot;">​</a></h2><p>Очередь пошива работает по принципу <strong>каскадного резервирования сверху вниз</strong>. Программа анализирует остатки на складе сырья и распределяет их между заказами в зависимости от их позиции (приоритета) в списке.</p><p>Вы можете управлять приоритетом с помощью кнопок-стрелок <strong>Вверх</strong> (↑) и <strong>Вниз</strong> (↓) на карточке заказа.</p><h3 id="как-работают-статусы" tabindex="-1">Как работают статусы: <a class="header-anchor" href="#как-работают-статусы" aria-label="Permalink to &quot;Как работают статусы:&quot;">​</a></h3><ul><li>✅ <strong>Обеспечен материалами:</strong> Для выполнения этого заказа на складе хватает свободного сырья.</li><li>⚠️ <strong>Дефицит сырья:</strong> Программа показывает, какого именно материала не хватает для старта.</li></ul><blockquote><p><strong>Пример из жизни:</strong> У вас на складе остался ровно 1 квадратный метр кожи. На верстаке висят два заказа: <em>Сумка</em> (расход 0.8 м²) и <em>Рюкзак</em> (расход 0.9 м²). Если Сумка находится в очереди <em>выше</em> Рюкзака, программа зарезервирует кожу под Сумку (статус: Обеспечен). А на Рюкзаке загорится Дефицит (не хватает 0.7 м²). Но если вы нажмете на Рюкзаке стрелку <strong>«Вверх»</strong> и поднимете его в приоритете, программа мгновенно пересчитает склад: Рюкзак заберет кожу себе (Обеспечен), а Сумка уйдет в Дефицит.</p></blockquote><p>Это позволяет вам накидывать план работы на недели вперед, даже если нужных материалов еще нет на складе. По мере проведения партионных закупок во вкладке «Сырьё», красные статусы дефицита на Верстаке будут автоматически становиться зелеными.</p><hr><h2 id="🏭-завершение-пошива-выпуск-продукции" tabindex="-1">🏭 Завершение пошива (Выпуск продукции) <a class="header-anchor" href="#🏭-завершение-пошива-выпуск-продукции" aria-label="Permalink to &quot;🏭 Завершение пошива (Выпуск продукции)&quot;">​</a></h2><p>Когда вы физически закончили шить партию изделий, нажмите синюю кнопку <strong>«Завершить пошив»</strong>. В эту секунду программа совершает сразу несколько важнейших фоновых операций:</p><ol><li><strong>Фактическое списание сырья:</strong> Зарезервированные материалы навсегда списываются со склада (из вкладки «Сырьё») с пометкой в журнале логистики. Отрицательный баланс допускается — если вы забыли провести закупку, склад уйдет в минус, но производство не заблокируется.</li><li><strong>Фиксация себестоимости:</strong> Программа делает «слепок» текущей цены. Она берет текущую стоимость сырья, вашу актуальную ставку мастера и накладные расходы, и <strong>навсегда замораживает</strong> эту цифру как себестоимость данной конкретной партии.</li><li><strong>Отправка на витрину (ФИФО):</strong> Готовые изделия зачисляются на склад готовой продукции (вкладка «Товары») в виде отдельной партии.</li></ol><div class="info custom-block"><p class="custom-block-title">Защита исторической стоимости (ФИФО)</p><p>Если вчера вы сшили кошелек из дешевой кожи (себестоимость 1000 ₽), а сегодня сшили такой же из дорогой (себестоимость 1500 ₽), на Витрине у вас будут лежать два кошелька. При продаже программа спишет их по методу <strong>ФИФО (First In, First Out)</strong> — сначала спишется старый кошелек за 1000 ₽, а затем новый за 1500 ₽. Это гарантирует 100% точность вашей итоговой прибыли.</p></div><hr><h2 id="❌-отмена-заказа" tabindex="-1">❌ Отмена заказа <a class="header-anchor" href="#❌-отмена-заказа" aria-label="Permalink to &quot;❌ Отмена заказа&quot;">​</a></h2><p>Если планы изменились, вы можете нажать кнопку <strong>«Отменить»</strong>. Заказ исчезнет с верстака, а все материалы, которые он резервировал под себя, мгновенно освободятся и перейдут к следующим заказам в очереди.</p><div class="warning custom-block"><p class="custom-block-title">Блокировка в Free-версии</p><p>Если вы используете бесплатную версию ОмниКрафт ЕРП и достигли лимита в 20 продаж, вкладка «Производство» перейдет в режим просмотра. На экране появится красное предупреждение, а кнопка «Завершить пошив» будет заблокирована до активации лицензионного ключа. Вы сможете отменять заказы, но не сможете выпускать новые товары.</p></div>',21)])])}const u=t(e,[["render",n]]);export{h as __pageData,u as default};
